rows1={1:[25,26,27,28,29],2:[25,29],3:[25,29],4:[5,6,7,8,9,18,19,20,24,25,29],5:[5,9,10,11,18,20,24,29],6:[5,11,18,20,24,25,26,27,28,29],7:[5,11,18,19,20],8:[5,6,7,8,11],9:[8,11],10:[8,9,10,11],11:[21,22,23,24,25,26],12:[21,26],13:[21,26],14:[21,26],15:[21,26],16:[8,9,10,11,12,13,14,15,16,21,22,23,24,26],17:[8,16],18:[8],19:[8,16],20:[8],21:[8,9,10,11,16],22:[11,16,22,23,24,25,26],23:[11,16,22,26],24:[11,12,13,14,15,16,22,23,26],25:[23,26],26:[23,24,25,26]}
grid=[[int(c in rows1.get(r,[])) for c in range(30)] for r in range(30)]
from collections import deque
R=C=30
ext=set(); q=deque()
for r in range(R):
 for c in range(C):
  if (r in (0,R-1) or c in (0,C-1)) and grid[r][c]==0 and (r,c) not in ext: ext.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  nr,nc=r+dr,c+dc
  if 0<=nr<R and 0<=nc<C and grid[nr][nc]==0 and (nr,nc) not in ext: ext.add((nr,nc));q.append((nr,nc))
interior={(r,c) for r in range(R) for c in range(C) if grid[r][c]==0 and (r,c) not in ext}
print('interior count',len(interior))
# 4-connected components of 1s
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c] and (r,c) not in seen:
   q=deque([(r,c)]);seen.add((r,c)); comp=[]
   while q:
    x=q.popleft();comp.append(x)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     p=x[0]+dr,x[1]+dc
     if 0<=p[0]<R and 0<=p[1]<C and grid[p[0]][p[1]] and p not in seen:seen.add(p);q.append(p)
   comps.append(comp)
print('components',len(comps),[(min(r for r,c in a),max(r for r,c in a),min(c for r,c in a),max(c for r,c in a),len(a)) for a in comps])
print('interior bounds', (min(r for r,c in interior), max(r for r,c in interior), min(c for r,c in interior),max(c for r,c in interior)) if interior else None)

# components of interior zero regions, summarize bbox and adjacent 1 components
ints_seen=set(); intcomps=[]
for p in interior:
 if p not in ints_seen:
  q=deque([p]);ints_seen.add(p); comp=[]
  while q:
   x=q.popleft();comp.append(x)
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    y=x[0]+dr,x[1]+dc
    if y in interior and y not in ints_seen:ints_seen.add(y);q.append(y)
  intcomps.append(comp)
print([(len(a),(min(r for r,c in a),max(r for r,c in a),min(c for r,c in a),max(c for r,c in a))) for a in intcomps])
for i,comp in enumerate(comps):
 adj=[(r,c) for r,c in comp if any((r+dr,c+dc) in interior for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))]
 print(i, 'bbox', (min(r for r,c in comp),max(r for r,c in comp),min(c for r,c in comp),max(c for r,c in comp)), 'adjacent interior',len(adj))

outs=[row[:] for row in grid]
closed=[]
for comp in comps:
 isclosed=any((r+dr,c+dc) in interior for r,c in comp for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
 closed.append(isclosed)
 if not isclosed:continue
 for r,c in comp:
  for dr in (-1,0,1):
   for dc in (-1,0,1):
    if dr==dc==0:continue
    nr,nc=r+dr,c+dc
    if 0<=nr<R and 0<=nc<C and grid[nr][nc]==0:
     outs[nr][nc]=3 if (nr,nc) in interior else 2
print('closed',closed)
for r,row in enumerate(outs):
 print(r,''.join(str(v) for v in row))
